"""Add experiments, their runs and the items each run stored.

Revision ID: 0506
Revises: 0505
Create Date: 2026-10-10

An experiment replays a dataset through one target (a prompt version or typed messages, sent
with an organization credential and a model) and scores every answer with the evaluators attached
to it. Each press of "Run" is an experiment run; each dataset item it reached is an experiment
item. Two runs are compared item by item.

Choices worth knowing about:

* Ids are UUIDv7 generated by the application, so no column has a default.
* `experiments` carries `project_id` and cascades from `projects`; `UNIQUE (project_id, name)`
  keeps names apart within a project, because the CLI and the CI action find an experiment by
  name. `config` is JSON validated by the API (a discriminated union of targets with the cost cap
  and the item limit); the database checks only that it is an object. `evaluator_ids` is a plain
  array, not foreign keys: an evaluator deleted later is skipped by the next run.
* `experiments.dataset_id` references `datasets` with `ON DELETE NO ACTION`: a dataset cannot be
  deleted while an experiment uses it (the API answers `409 DATASET_IN_USE` first). `NO ACTION`
  rather than `RESTRICT` because the check runs at the end of the statement, so deleting a
  project, which cascades to both tables, still works.
* `experiment_runs` and `experiment_items` have no `project_id`: a run belongs to its experiment
  and an item to its run, and both cascade. Their row-level security policies ask whether the
  parent is visible, in the same InitPlan form as the project policies, so they are exactly as
  visible as the experiment.
* `experiment_runs.number` counts an experiment's runs from 1 ("Run 3"). It is assigned under the
  experiment's row lock when the run is queued and never changes; `UNIQUE (experiment_id,
  number)` backs it and serves the "next number" lookup.
* `experiment_runs.target` is the target the run actually used: the experiment's, or, for a
  prompt-version target, the same prompt at another version when the run was started with an
  override. Two runs of one experiment can then compare two versions on the same dataset.
* At most one run per experiment is `queued` or `running`: the partial unique index
  `experiment_runs_active_key` enforces it (the API answers `409 RUN_IN_PROGRESS`). The same
  index serves the reaper, which reads only non-terminal runs. A finished run has `finished_at`,
  an unfinished one does not (CHECK).
* `experiment_items` is keyed by `(run_id, dataset_item_id)`, so a run stores each item once.
  `dataset_item_id` and `trace_id` are plain values, not foreign keys: a dataset item may be
  removed and a trace deleted by retention while the run's record of them must stay comparable.
  `cost_usd` is NULL when the model has no price or the provider reported no usage; never 0.
  `error` says why the item has no answer; `evaluator_error` says that scoring an answer broke
  (the answer and its cost stay).
* Indexes: `(dataset_id)` serves the "dataset in use" check, `(experiment_id, started_at DESC)`
  the runs listing, `(trace_id)` the experiment item of a trace, `(project_id, created_at DESC)`
  the experiments listing; `created_by` and `started_by` are indexed so deleting a user does not
  scan the tables.

The migration creates new tables only, in one transaction. Downgrade drops them.
"""

from collections.abc import Sequence

from alembic import op

revision: str = "0506"
down_revision: str | None = "0505"
branch_labels: str | Sequence[str] | None = None
depends_on: str | Sequence[str] | None = None

PROJECT_EXPRESSION = (
    "project_id = (SELECT NULLIF(current_setting('app.project_id', true), '')::uuid)"
)
BYPASS_EXPRESSION = "(SELECT current_setting('app.bypass_rls', true)) = 'on'"
RUN_EXPRESSION = "EXISTS (SELECT 1 FROM experiments x WHERE x.id = experiment_runs.experiment_id)"
ITEM_EXPRESSION = "EXISTS (SELECT 1 FROM experiment_runs r WHERE r.id = experiment_items.run_id)"


def upgrade() -> None:
    _create_experiments()
    _create_runs()
    _create_items()
    _enable_rls()


def _create_experiments() -> None:
    op.execute(
        """
        CREATE TABLE experiments (
            id             uuid PRIMARY KEY,
            project_id     uuid NOT NULL REFERENCES projects (id) ON DELETE CASCADE,
            name           text NOT NULL CHECK (char_length(name) BETWEEN 1 AND 200),
            dataset_id     uuid NOT NULL REFERENCES datasets (id) ON DELETE NO ACTION,
            config         jsonb NOT NULL CHECK (jsonb_typeof(config) = 'object'),
            evaluator_ids  uuid[] NOT NULL DEFAULT '{}'
                           CHECK (cardinality(evaluator_ids) <= 20),
            created_by     uuid REFERENCES users (id) ON DELETE SET NULL,
            created_at     timestamptz NOT NULL DEFAULT now(),
            CONSTRAINT experiments_project_name_key UNIQUE (project_id, name)
        )
        """
    )
    op.execute("CREATE INDEX experiments_dataset_idx ON experiments (dataset_id)")
    op.execute(
        "CREATE INDEX experiments_project_created_idx "
        "ON experiments (project_id, created_at DESC, id DESC)"
    )
    op.execute("CREATE INDEX experiments_created_by_idx ON experiments (created_by)")


def _create_runs() -> None:
    op.execute(
        """
        CREATE TABLE experiment_runs (
            id             uuid PRIMARY KEY,
            experiment_id  uuid NOT NULL REFERENCES experiments (id) ON DELETE CASCADE,
            number         integer NOT NULL CHECK (number >= 1),
            target         jsonb NOT NULL CHECK (jsonb_typeof(target) = 'object'),
            status         text NOT NULL DEFAULT 'queued'
                           CHECK (status IN ('queued', 'running', 'done', 'failed')),
            error          text CHECK (char_length(error) <= 500),
            started_at     timestamptz NOT NULL DEFAULT now(),
            finished_at    timestamptz,
            heartbeat_at   timestamptz,
            totals         jsonb CHECK (totals IS NULL OR jsonb_typeof(totals) = 'object'),
            started_by     uuid REFERENCES users (id) ON DELETE SET NULL,
            CONSTRAINT experiment_runs_number_key UNIQUE (experiment_id, number),
            CONSTRAINT experiment_runs_finished_check
                CHECK ((status IN ('done', 'failed')) = (finished_at IS NOT NULL))
        )
        """
    )
    op.execute(
        "CREATE INDEX experiment_runs_experiment_started_idx "
        "ON experiment_runs (experiment_id, started_at DESC, id DESC)"
    )
    op.execute(
        "CREATE UNIQUE INDEX experiment_runs_active_key ON experiment_runs (experiment_id) "
        "WHERE status IN ('queued', 'running')"
    )
    op.execute("CREATE INDEX experiment_runs_started_by_idx ON experiment_runs (started_by)")


def _create_items() -> None:
    op.execute(
        """
        CREATE TABLE experiment_items (
            run_id           uuid NOT NULL REFERENCES experiment_runs (id) ON DELETE CASCADE,
            dataset_item_id  uuid NOT NULL,
            trace_id         text,
            output           jsonb,
            scores           jsonb NOT NULL DEFAULT '{}'
                             CHECK (jsonb_typeof(scores) = 'object'),
            latency_ms       double precision CHECK (latency_ms >= 0),
            cost_usd         numeric(14, 8) CHECK (cost_usd >= 0),
            error            text CHECK (char_length(error) <= 500),
            evaluator_error  text CHECK (char_length(evaluator_error) <= 500),
            created_at       timestamptz NOT NULL DEFAULT now(),
            PRIMARY KEY (run_id, dataset_item_id)
        )
        """
    )
    op.execute("CREATE INDEX experiment_items_trace_idx ON experiment_items (trace_id)")


def _enable_rls() -> None:
    _policies("experiments", PROJECT_EXPRESSION)
    _policies("experiment_runs", RUN_EXPRESSION)
    _policies("experiment_items", ITEM_EXPRESSION)


def _policies(table: str, visible: str) -> None:
    op.execute(f"ALTER TABLE {table} ENABLE ROW LEVEL SECURITY")
    op.execute(f"ALTER TABLE {table} FORCE ROW LEVEL SECURITY")
    op.execute(
        f"CREATE POLICY {table}_project_isolation ON {table} "
        f"USING ({visible}) WITH CHECK ({visible})"
    )
    op.execute(
        f"CREATE POLICY {table}_worker_bypass ON {table} "
        f"USING ({BYPASS_EXPRESSION}) WITH CHECK ({BYPASS_EXPRESSION})"
    )


def downgrade() -> None:
    op.execute("DROP TABLE IF EXISTS experiment_items")
    op.execute("DROP TABLE IF EXISTS experiment_runs")
    op.execute("DROP TABLE IF EXISTS experiments")
